import express from "express";
import { SLUG_PATTERN, deletePage, listSlugs, readPage, writePage } from "./pages.js";
import { PageIndex } from "./index.js";

function requireValidSlug(req, res, next) {
  if (!SLUG_PATTERN.test(req.params.slug)) return res.status(400).json({ error: "invalid slug" });
  return next();
}

export function createApp(options = {}) {
  const pagesDir = options.pagesDir;
  if (!pagesDir) throw new TypeError("pagesDir is required");
  const indexPath = options.indexPath ?? process.env.WIKI_INDEX_PATH ?? "wiki-index.sqlite";
  const index = new PageIndex(indexPath);
  index.replaceAll(listSlugs(pagesDir).map((slug) => readPage(pagesDir, slug)));
  const app = express();
  app.disable("x-powered-by");
  app.use(express.json({ limit: "256kb" }));

  app.get("/pages", (_req, res) => {
    res.json(listSlugs(pagesDir).map((slug) => {
      const { title, tags } = readPage(pagesDir, slug);
      return { slug, title, tags };
    }));
  });

  app.get("/pages/:slug", requireValidSlug, (req, res) => {
    const page = readPage(pagesDir, req.params.slug);
    if (!page) return res.status(404).json({ error: "page not found" });
    return res.json(page);
  });

  app.put("/pages/:slug", requireValidSlug, (req, res) => {
    const body = req.body?.body;
    if (typeof body !== "string") return res.status(400).json({ error: "body must be a string" });
    const existed = writePage(pagesDir, req.params.slug, body);
    index.upsert(readPage(pagesDir, req.params.slug));
    return res.status(existed ? 200 : 201).json(readPage(pagesDir, req.params.slug));
  });

  app.delete("/pages/:slug", requireValidSlug, (req, res) => {
    if (!deletePage(pagesDir, req.params.slug)) return res.status(404).json({ error: "page not found" });
    index.remove(req.params.slug);
    return res.status(204).end();
  });

  app.get("/search", (req, res) => {
    const query = typeof req.query.q === "string" ? req.query.q : "";
    if (!query.trim()) return res.status(400).json({ error: "q is required" });
    return res.json({ query, results: index.search(query) });
  });

  app.get("/tags", (_req, res) => res.json(index.tags()));
  app.get("/tags/:tag", (req, res) => res.json(index.pagesForTag(req.params.tag)));

  app.locals.close = () => index.close();
  return app;
}
import { readdirSync, readFileSync, writeFileSync, rmSync, existsSync } from "node:fs";
import { join } from "node:path";

export const SLUG_PATTERN = /^[a-z0-9-]+$/;
const PAGE_EXTENSION = ".md";

export function pagePath(pagesDir, slug) {
  return join(pagesDir, `${slug}${PAGE_EXTENSION}`);
}

export function parsePage(slug, markdown) {
  let content = markdown;
  let frontMatter = "";
  const opening = /^(?:\uFEFF)?---\r?\n/.exec(markdown);
  if (opening) {
    const closing = /^(?:---|\.\.\.)[ \t]*\r?$/m;
    const rest = markdown.slice(opening[0].length);
    const match = closing.exec(rest);
    if (match) {
      frontMatter = rest.slice(0, match.index);
      content = rest.slice(match.index + match[0].length).replace(/^\r?\n/, "");
    }
  }

  let frontTitle;
  let tags = [];
  for (const line of frontMatter.split(/\r?\n/)) {
    const field = /^\s*(title|tags)\s*:\s*(.*?)\s*$/.exec(line);
    if (!field) continue;
    if (field[1] === "title") frontTitle = field[2].replace(/^(?:["'])(.*)(?:["'])$/, "$1").trim();
    if (field[1] === "tags") {
      const value = field[2].replace(/^\[(.*)\]$/, "$1");
      tags = [...new Set(value.split(",").map((tag) => tag.trim().replace(/^(?:["'])(.*)(?:["'])$/, "$1").toLowerCase()).filter(Boolean))].sort();
    }
  }
  const heading = content.split(/\r?\n/).find((line) => line.startsWith("# "));
  const title = frontTitle || (heading ? heading.slice(2).trim() : slug);
  return { slug, title, tags, body: content };
}

export function titleFor(slug, markdown) {
  return parsePage(slug, markdown).title;
}

export function listSlugs(pagesDir) {
  return readdirSync(pagesDir)
    .filter((file) => file.endsWith(PAGE_EXTENSION))
    .map((file) => file.slice(0, -PAGE_EXTENSION.length))
    .filter((slug) => SLUG_PATTERN.test(slug))
    .sort();
}

export function readPage(pagesDir, slug) {
  const path = pagePath(pagesDir, slug);
  if (!existsSync(path)) return undefined;
  return parsePage(slug, readFileSync(path, "utf8"));
}

export function writePage(pagesDir, slug, body) {
  const existed = existsSync(pagePath(pagesDir, slug));
  writeFileSync(pagePath(pagesDir, slug), body);
  return existed;
}

export function deletePage(pagesDir, slug) {
  const path = pagePath(pagesDir, slug);
  if (!existsSync(path)) return false;
  rmSync(path);
  return true;
}
import { readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { execFileSync } from "node:child_process";

const SOURCE_DIRECTORIES = ["src", "test", "bin"];
const SKIPPED_DIRECTORIES = new Set(["node_modules", ".git", ".acceptance"]);

function listJavaScriptFiles(directory) {
  let entries;
  try { entries = readdirSync(directory); } catch { return []; }
  return entries.flatMap((entry) => {
    if (SKIPPED_DIRECTORIES.has(entry)) return [];
    const path = join(directory, entry);
    if (statSync(path).isDirectory()) return listJavaScriptFiles(path);
    return /\.(c|m)?js$/.test(entry) ? [path] : [];
  });
}

